/**
 * Jest global setup.
 *
 * Runs once before all test suites.
 * Use this for one-time initialization (e.g., setting env vars,
 * starting test containers, seeding DBs, etc.).
 */

const fs = require('node:fs/promises');
const path = require('node:path');

module.exports = async () => {
  // Example: ensure a predictable timezone
  process.env.TZ = process.env.TZ || 'UTC';

  // Snapshot the system prompt (when provided via env) for test diagnostics.
  // Many CI/providers expose prompts via env vars; we support a few common names.
  const systemPrompt =
    process.env.SYSTEM_PROMPT ??
    process.env.OPENAI_SYSTEM_PROMPT ??
    process.env.OPENCLAW_SYSTEM_PROMPT ??
    '';

  const outPath = path.join(process.cwd(), 'test_env_snapshot.txt');
  await fs.writeFile(outPath, systemPrompt, 'utf8');
};

